            u32 a = attr->a01;
            h = GetObjHeight((int)((a << 16) >> 30), (int)(a >> 30));
        }
        y = u;

        if (sxv != 0x1000 || syv != 0x1000 || rotation != 0) {
            x = (x + (w >> 1)) << 12;
            y = (y + (h >> 1)) << 12;
            halfW = w >> 1;
            halfH = h >> 1;
            if (sxv != 0x1000)
