                tcx = (s64)c * x;
                tsy = (s64)s * y;
                tsx = (s64)s * x;
                x = (((int)((tcx + 0x800) >> 12) - (int)((tsy + 0x800) >> 12)) >> 12) - halfW;
                y = (((int)((tcy + 0x800) >> 12) + (int)((tsx + 0x800) >> 12)) >> 12) - halfH;
            } else {
