                y = (y >> 12) - halfH;
            }
            if (((attr->a01 << 22) >> 30) != 1) {
                w <<= 1;
                x -= halfW;
                h <<= 1;
                y -= halfH;
            }
        }

        x += xOff;
        y += yOff;

        if (rotation != 0) {
            if (w < h)
                w = h;
            if (x + w < 0 || x > 0x100) {
                if (attr->a3 == 0xffff) return;
                attr++;
                continue;
            }
            if (y + w < 0 || y > 0xc0) {
                if (attr->a3 == 0xffff) return;
                attr++;
                continue;
            }
        } else {
            if (x + w < 0 || x > 0x100) {
                if (attr->a3 == 0xffff) return;
                attr++;
                continue;
            }
            if (y + h < 0 || y > 0xc0) {
                if (attr->a3 == 0xffff) return;
                attr++;
                continue;
            }
        }

        }
        }
        if (palette == -1)
            palVal = (int)((*(u32 *)&attr->a2 << 16) >> 28);
        else
            palVal = palette;
        if (priority == -1)
            priVal = (int)((*(u32 *)&attr->a2 << 20) >> 30);
        else
            priVal = priority;
        if (mode > 0)
            om = mode;
        else
            om = (int)((attr->a01 << 20) >> 30);

        {
            int aff;
            u32 ipVal;
            if (sxv != 0x1000 || syv != 0x1000 || rotation != 0) {
